    "glyhub.cache_dir",
    tools::R_user_dir("glyhub", "cache")
  ),
  refresh = FALSE,
  offline = FALSE
) {
  glyhub_load("glyhub_GPST000671_N", kind, cache_dir, refresh, offline)
}

